-- Generated by model/lib/sql/generate.mjs. L1's load of Marketing Spend IN from cells/Marketing Spend IN.csv in the folder of input cells, into its empty table.
-- Two rows for one cell add up.
-- @csv cells/Marketing Spend IN.csv
INSERT INTO "Marketing Spend IN" SELECT coalesce(k0."Brand", fpabench_error('cells name a member Brand does not have: ' || c."Brand")), coalesce(k1."Versions", fpabench_error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k2."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k3."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Brand" k0 ON k0.name = c."Brand" LEFT JOIN "dim Versions" k1 ON k1.name = c."Versions" LEFT JOIN "dim Years" k2 ON k2.name = c."Years" LEFT JOIN "dim Months" k3 ON k3.name = c."Months"
GROUP BY 1, 2, 3, 4;
ANALYZE "Marketing Spend IN";
